-- Lower-case alias without the slash to its entry; the first owner wins.
---@type table<string, MacroAssistCommand>
ns.CommandAliases = {}
for _, command in ipairs(ns.Commands) do
	for _, alias in ipairs(command.aliases) do
		if ns.CommandAliases[alias] == nil then
			ns.CommandAliases[alias] = command
		end
	end
	if ns.CommandAliases[command.name] == nil then
		ns.CommandAliases[command.name] = command
	end
end
